{
  "name": "contextpack",
  "version": "1.0.0",
  "description": "Bundle your codebase into a single LLM-ready file. Stop copy-pasting files into Claude/ChatGPT.",
  "main": "dist/index.js",
  "types": "dist/types/index.d.ts",
  "bin": {
    "contextpack": "./dist/cli.js",
    "ctx": "./dist/cli.js"
  },
  "scripts": {
    "build": "tsup src/index.ts src/cli.ts --format cjs --dts --clean",
    "dev": "tsx src/cli.ts",
    "start": "node dist/cli.js"
  },
  "keywords": [
    "llm", "ai", "context", "codebase", "claude", "chatgpt",
    "openai", "developer-tools", "cli", "typescript"
  ],
  "author": "",
  "license": "MIT",
  "engines": {
    "node": ">=16.0.0"
  },
  "dependencies": {
    "chokidar": "^3.6.0",
    "clipboardy": "^4.0.0",
    "chalk": "^5.3.0",
    "ignore": "^5.3.1",
    "minimist": "^1.2.8"
  },
  "devDependencies": {
    "@types/minimist": "^1.2.5",
    "@types/node": "^20.0.0",
    "tsup": "^8.0.0",
    "tsx": "^4.0.0",
    "typescript": "^5.0.0"
  }
}

#!/usr/bin/env node
import * as fs from 'fs';
import * as path from 'path';
import minimist from 'minimist';
import { pack } from './index.js';
import { watch } from './watcher.js';
import { ContextPackOptions } from './types.js';
import { formatTokenCount, getContextWarning } from './tokenEstimator.js';

const HELP = `
╔═══════════════════════════════════════════╗
║           contextpack (ctx)               ║
║  Bundle your codebase for LLMs instantly  ║
╚═══════════════════════════════════════════╝

Usage:
  ctx [directory] [options]
  contextpack [directory] [options]

Options:
  --out, -o       Output file path (default: context.md)
  --format, -f    Output format: markdown | json (default: markdown)
  --include, -i   Only include paths matching pattern (repeatable)
  --exclude, -e   Exclude paths matching pattern (repeatable)
  --copy, -c      Copy output to clipboard
  --watch, -w     Watch for changes and repack automatically
  --stats, -s     Print stats only, no file contents
  --max-size      Max file size in KB to include (default: 500)
  --help, -h      Show this help message

Examples:
  ctx .
  ctx ./src --out context.md
  ctx . --format json --out context.json
  ctx . --include src --exclude tests
  ctx . --copy
  ctx . --watch --out context.md
  ctx . --stats
`;

async function main() {
  const argv = minimist(process.argv.slice(2), {
    string: ['out', 'format', 'include', 'exclude'],
    boolean: ['copy', 'watch', 'stats', 'help'],
    alias: {
      o: 'out',
      f: 'format',
      i: 'include',
      e: 'exclude',
      c: 'copy',
      w: 'watch',
      s: 'stats',
      h: 'help',
    },
    default: {
      format: 'markdown',
      copy: false,
      watch: false,
      stats: false,
    },
  });

  if (argv.help) {
    console.log(HELP);
    process.exit(0);
  }

  const dir = argv._[0] || '.';

  if (!fs.existsSync(dir)) {
    console.error(`❌ Directory not found: ${dir}`);
    process.exit(1);
  }

  const format = argv.format === 'json' ? 'json' : 'markdown';
  const defaultOut = format === 'json' ? 'context.json' : 'context.md';
  const outPath = path.resolve(argv.out || defaultOut);

  const options: ContextPackOptions = {
    dir,
    format,
    out: outPath,
    copy: argv.copy,
    watch: argv.watch,
    stats: argv.stats,
    maxFileSize: (argv['max-size'] || 500) * 1024,
    include: argv.include
      ? Array.isArray(argv.include) ? argv.include : [argv.include]
      : undefined,
    exclude: argv.exclude
      ? Array.isArray(argv.exclude) ? argv.exclude : [argv.exclude]
      : undefined,
  };

  // Watch mode
  if (options.watch) {
    watch(options, outPath);
    return;
  }

  // Single pack
  console.log(`\n📦 Packing ${path.resolve(dir)}...\n`);

  try {
    const { output, result } = pack(options);

    // Stats only mode
    if (options.stats) {
      console.log(`📊 Stats`);
      console.log(`   Files:   ${result.totalFiles}`);
      console.log(`   Size:    ${(result.totalSizeBytes / 1024).toFixed(1)} KB`);
      console.log(`   Tokens:  ${formatTokenCount(result.totalTokens)}`);
      const warning = getContextWarning(result.totalTokens);
      if (warning) console.log(`\n   ${warning}`);
      console.log('');
      return;
    }

    // Write output file
    fs.writeFileSync(outPath, output, 'utf-8');
    console.log(`✅ Done!`);
    console.log(`   Files:   ${result.totalFiles}`);
    console.log(`   Tokens:  ${formatTokenCount(result.totalTokens)}`);
    console.log(`   Output:  ${outPath}`);

    const warning = getContextWarning(result.totalTokens);
    if (warning) console.log(`\n   ${warning}`);

    // Copy to clipboard
    if (options.copy) {
      try {
        const { default: clipboardy } = await import('clipboardy');
        await clipboardy.write(output);
        console.log(`\n📋 Copied to clipboard!`);
      } catch {
        console.warn(`\n⚠️  Could not copy to clipboard`);
      }
    }

    console.log('');
  } catch (err) {
    console.error(`❌ Failed to pack:`, err);
    process.exit(1);
  }
}

main();

import { PackResult, ContextPackOptions } from './types.js';
import { formatTokenCount, getContextWarning } from './tokenEstimator.js';

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
}

export function formatMarkdown(result: PackResult, options: ContextPackOptions): string {
  const warning = getContextWarning(result.totalTokens);
  const lines: string[] = [];

  // Header
  lines.push('# ContextPack');
  lines.push('');
  lines.push(`> Generated by [contextpack](https://github.com/HalxDocs/contextpack) — ${result.generatedAt}`);
  lines.push('');

  // Stats
  lines.push('## 📊 Stats');
  lines.push('');
  lines.push(`| Property | Value |`);
  lines.push(`|----------|-------|`);
  lines.push(`| Source | \`${result.sourceDir}\` |`);
  lines.push(`| Files | ${result.totalFiles} |`);
  lines.push(`| Total Size | ${formatBytes(result.totalSizeBytes)} |`);
  lines.push(`| Estimated Tokens | ${formatTokenCount(result.totalTokens)} |`);
  lines.push('');

  if (warning) {
    lines.push(`> ${warning}`);
    lines.push('');
  }

  // File Tree
  lines.push('## 🗂 File Tree');
  lines.push('');
  lines.push('```');
  lines.push(result.fileTree);
  lines.push('```');
  lines.push('');

  // Files
  lines.push('## 📄 Files');
  lines.push('');

  for (const file of result.files) {
    lines.push(`### \`${file.relativePath}\``);
    lines.push('');
    lines.push(`> ${formatBytes(file.sizeBytes)} · ${formatTokenCount(file.tokens)}`);
    lines.push('');
    lines.push(`\`\`\`${file.language}`);
    lines.push(file.content);
    lines.push('```');
    lines.push('');
  }

  return lines.join('\n');
}

export function formatJSON(result: PackResult): string {
  return JSON.stringify(
    {
      meta: {
        generatedAt: result.generatedAt,
        sourceDir: result.sourceDir,
        totalFiles: result.totalFiles,
        totalSizeBytes: result.totalSizeBytes,
        totalTokens: result.totalTokens,
      },
      fileTree: result.fileTree,
      files: result.files.map(f => ({
        path: f.relativePath,
        language: f.language,
        sizeBytes: f.sizeBytes,
        tokens: f.tokens,
        content: f.content,
      })),
    },
    null,
    2
  );
}

import * as path from 'path';
import { walkDir, buildFileTree } from './walker.js';
import { formatMarkdown, formatJSON } from './formatter.js';
import { ContextPackOptions, PackResult } from './types.js';

export function pack(options: ContextPackOptions): { output: string; result: PackResult } {
  const dir = path.resolve(options.dir);

  // Walk the directory and collect files
  const files = walkDir(dir, {
    exclude: options.exclude,
    maxFileSize: options.maxFileSize,
  });

  // Filter by include patterns if provided
  const filteredFiles = options.include
    ? files.filter(f =>
        options.include!.some(pattern => f.relativePath.includes(pattern))
      )
    : files;

  // Build the result object
  const result: PackResult = {
    files: filteredFiles,
    fileTree: buildFileTree(filteredFiles),
    totalFiles: filteredFiles.length,
    totalSizeBytes: filteredFiles.reduce((sum, f) => sum + f.sizeBytes, 0),
    totalTokens: filteredFiles.reduce((sum, f) => sum + f.tokens, 0),
    generatedAt: new Date().toISOString(),
    sourceDir: dir,
  };

  // Format output
  const output =
    options.format === 'json'
      ? formatJSON(result)
      : formatMarkdown(result, options);

  return { output, result };
}

export { ContextPackOptions, PackResult, FileEntry } from './types.js';

// It approximates token count the same way OpenAI/Claude tokenizers work
// ~4 characters per token is the widely accepted estimate

export function estimateTokens(text: string): number {
  return Math.ceil(text.length / 4);
}

export function formatTokenCount(tokens: number): string {
  if (tokens < 1000) return `${tokens} tokens`;
  if (tokens < 1_000_000) return `${(tokens / 1000).toFixed(1)}k tokens`;
  return `${(tokens / 1_000_000).toFixed(2)}M tokens`;
}

export function getContextWarning(tokens: number): string | null {
  if (tokens > 2_000_000) return '⛔ Exceeds most LLM context windows (2M+)';
  if (tokens > 1_000_000) return '⚠️  Very large — only Gemini 1.5 / Claude 3 can handle this';
  if (tokens > 200_000)   return '⚠️  Large — works with Claude 3, GPT-4 Turbo';
  if (tokens > 128_000)   return '⚠️  Fits Claude 3 but may exceed GPT-4';
  return null;
}

export interface ContextPackOptions {
  dir: string;
  include?: string[];
  exclude?: string[];
  format: 'markdown' | 'json';
  out?: string;
  copy: boolean;
  watch: boolean;
  stats: boolean;
  maxFileSize: number;
}

export interface FileEntry {
  path: string;
  relativePath: string;
  extension: string;
  language: string;
  content: string;
  sizeBytes: number;
  tokens: number;
}

export interface PackResult {
  files: FileEntry[];
  fileTree: string;
  totalFiles: number;
  totalSizeBytes: number;
  totalTokens: number;
  generatedAt: string;
  sourceDir: string;
}

import * as fs from 'fs';
import * as path from 'path';
import ignore, { Ignore } from 'ignore';
import { FileEntry } from './types.js';
import { estimateTokens } from './tokenEstimator.js';

const LANGUAGE_MAP: Record<string, string> = {
  ts: 'typescript', tsx: 'typescript', js: 'javascript', jsx: 'javascript',
  py: 'python', rb: 'ruby', go: 'go', rs: 'rust', java: 'java',
  cpp: 'cpp', c: 'c', cs: 'csharp', php: 'php', swift: 'swift',
  kt: 'kotlin', scala: 'scala', html: 'html', css: 'css', scss: 'scss',
  json: 'json', yaml: 'yaml', yml: 'yaml', toml: 'toml', md: 'markdown',
  sh: 'bash', bash: 'bash', zsh: 'bash', sql: 'sql', graphql: 'graphql',
  vue: 'vue', svelte: 'svelte', xml: 'xml', dockerfile: 'dockerfile',
};

const ALWAYS_IGNORE = [
  'node_modules', '.git', 'dist', 'build', '.next', '.nuxt',
  'coverage', '.cache', '.turbo', 'out', '.vercel', '.netlify',
  '*.lock', '*.log', '*.map', '*.min.js', '*.min.css',
  '*.jpg', '*.jpeg', '*.png', '*.gif', '*.ico', '*.svg',
  '*.mp4', '*.mp3', '*.zip', '*.tar', '*.gz', '*.exe',
  '*.pdf', '*.ttf', '*.woff', '*.woff2', '*.eot',
];

function getLanguage(ext: string, filename: string): string {
  if (filename.toLowerCase() === 'dockerfile') return 'dockerfile';
  return LANGUAGE_MAP[ext.toLowerCase()] || ext || 'text';
}

function buildIgnore(dir: string, extraExcludes: string[]): Ignore {
  const ig = ignore();
  ig.add(ALWAYS_IGNORE);
  ig.add(extraExcludes);

  const gitignorePath = path.join(dir, '.gitignore');
  if (fs.existsSync(gitignorePath)) {
    const gitignoreContent = fs.readFileSync(gitignorePath, 'utf-8');
    ig.add(gitignoreContent);
  }

  return ig;
}

export function walkDir(
  dir: string,
  options: { exclude?: string[]; maxFileSize?: number }
): FileEntry[] {
  const ig = buildIgnore(dir, options.exclude || []);
  const maxSize = options.maxFileSize ?? 500 * 1024; // 500kb default
  const files: FileEntry[] = [];

  function walk(currentDir: string) {
    const entries = fs.readdirSync(currentDir, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(currentDir, entry.name);
      const relativePath = path.relative(dir, fullPath).replace(/\\/g, '/');

      if (ig.ignores(relativePath)) continue;

      if (entry.isDirectory()) {
        walk(fullPath);
      } else if (entry.isFile()) {
        const stat = fs.statSync(fullPath);
        if (stat.size > maxSize) continue;

        let content: string;
        try {
          content = fs.readFileSync(fullPath, 'utf-8');
        } catch {
          continue; // skip binary files that can't be read as utf-8
        }

        const ext = path.extname(entry.name).replace('.', '');
        const language = getLanguage(ext, entry.name);

        files.push({
          path: fullPath,
          relativePath,
          extension: ext,
          language,
          content,
          sizeBytes: stat.size,
          tokens: estimateTokens(content),
        });
      }
    }
  }

  walk(dir);
  return files.sort((a, b) => a.relativePath.localeCompare(b.relativePath));
}

export function buildFileTree(files: FileEntry[]): string {
  const lines: string[] = [];
  const dirs = new Set<string>();

  for (const file of files) {
    const parts = file.relativePath.split('/');
    for (let i = 1; i < parts.length; i++) {
      dirs.add(parts.slice(0, i).join('/'));
    }
  }

  const allPaths = [
    ...Array.from(dirs).map(d => ({ path: d, isDir: true })),
    ...files.map(f => ({ path: f.relativePath, isDir: false })),
  ].sort((a, b) => a.path.localeCompare(b.path));

  for (const item of allPaths) {
    const depth = item.path.split('/').length - 1;
    const indent = '  '.repeat(depth);
    const name = item.path.split('/').pop()!;
    lines.push(`${indent}${item.isDir ? '📁' : '📄'} ${name}`);
  }

  return lines.join('\n');
}

import * as fs from 'fs';
import * as path from 'path';
import chokidar from 'chokidar';
import { pack } from './index.js';
import { ContextPackOptions } from './types.js';
import { formatTokenCount } from './tokenEstimator.js';

export function watch(options: ContextPackOptions, outPath: string) {
  const dir = path.resolve(options.dir);

  console.log(`\n👀 Watching ${dir} for changes...`);
  console.log(`📦 Output: ${outPath}`);
  console.log(`Press Ctrl+C to stop\n`);

  function rebuild(changedPath?: string) {
    if (changedPath) {
      const rel = path.relative(dir, changedPath).replace(/\\/g, '/');
      console.log(`🔄 Change detected: ${rel}`);
    }

    try {
      const { output, result } = pack(options);
      fs.writeFileSync(outPath, output, 'utf-8');

      const time = new Date().toLocaleTimeString();
      console.log(
        `✅ [${time}] Repacked → ${result.totalFiles} files · ${formatTokenCount(result.totalTokens)}`
      );
    } catch (err) {
      console.error(`❌ Error repacking:`, err);
    }
  }

  // Initial build
  rebuild();

  // Watch for changes
  const watcher = chokidar.watch(dir, {
    ignored: [
      /(^|[\/\\])\../, // dotfiles
      /node_modules/,
      /dist/,
      /\.git/,
      outPath, // ignore the output file itself
    ],
    persistent: true,
    ignoreInitial: true,
  });

  watcher
    .on('add', rebuild)
    .on('change', rebuild)
    .on('unlink', rebuild)
    .on('addDir', rebuild)
    .on('unlinkDir', rebuild);

  // Graceful shutdown
  process.on('SIGINT', () => {
    console.log('\n\n👋 Stopping watcher...');
    watcher.close();
    process.exit(0);
  });
}
